importScripts('./vendor/sql-wasm.js');
onmessage=async e=>{let db;try{const SQL=await initSqlJs({locateFile:file=>new URL('./vendor/'+file,self.location.href).href});db=new SQL.Database(new Uint8Array(e.data));const count=db.exec('SELECT COUNT(*) FROM notes')[0]?.values[0][0];if(count>10000)throw new Error('Maximum 10,000 notes per import.');const rows=db.exec('SELECT id, flds FROM notes ORDER BY id')[0]?.values||[];postMessage({notes:rows.map(([id,flds])=>({id:String(id),fields:String(flds).split('\x1f')}))});}catch(e){postMessage({error:e.message||'Invalid Anki database.'});}finally{db?.close();}};
